const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axePath = require.resolve('axe-core/axe.min.js');

(async () => {
  const html = fs.readFileSync(path.resolve('index.html'), 'utf8');
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(html, { waitUntil: 'load' });

  async function runAxe(label) {
    await page.addScriptTag({ path: axePath });
    const result = await page.evaluate(async () => window.axe.run());
    const wcag = result.violations.filter((v) => !v.tags.includes('best-practice'));
    return {
      label,
      wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
    };
  }

  const closed = await runAxe('closed');
  await page.click('.trigger');
  const isOpen = await page.locator('#delete-dialog').evaluate((dialog) => dialog.open);
  if (!isOpen) throw new Error('Dialog did not open from .trigger');
  const activeText = await page.evaluate(() => document.activeElement.textContent.trim());
  if (activeText !== 'Cancel') throw new Error(`Expected initial focus on Cancel, got ${activeText}`);
  const open = await runAxe('open');
  await browser.close();

  const failures = [closed, open].filter((entry) => entry.wcag.length);
  console.log(JSON.stringify({ closed: closed.wcag, open: open.wcag }, null, 2));
  process.exit(failures.length ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
