      .map((v) => ({ state: check.label, id: v.id, impact: v.impact, targets: v.targets }))
  );

  console.log(JSON.stringify({ wcagFailures, bestPracticeWarnings }, null, 2));
  process.exit(wcagFailures.length ? 1 : 0);
})().catch(async (error) => {
  console.error(error.message);
  process.exit(2);
});
