                <a class="button button-secondary" href="#">Download</a>
              </div>
              <p class="status" id="delete-status" role="status" aria-live="polite" tabindex="-1">
                ${isDeleted ? "Image deleted from your library." : ""}
              </p>
            </div>
          </article>
        `;
      }

      function DetailsPanel() {
        return `
          <section class="details-card" aria-labelledby="details-title">
            <h2 id="details-title">File details</h2>
            <ul class="meta-list">
              <li class="meta-item">
                <span class="meta-label">Type</span>
                <span class="meta-value">Landscape photo</span>
              </li>
              <li class="meta-item">
                <span class="meta-label">Resolution</span>
                <span class="meta-value">4800 x 3000</span>
              </li>
              <li class="meta-item">
                <span class="meta-label">Saved</span>
                <span class="meta-value">Private library</span>
              </li>
            </ul>
          </section>
        `;
      }

      function DeleteDialog() {
        return `
          <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
            <div class="dialog-content">
              <div class="dialog-icon" aria-hidden="true">!</div>
              <h2 id="delete-dialog-title">Delete this image?</h2>
              <p id="delete-dialog-description">
                This will remove "${image.title}" from your library. This action cannot be undone.
              </p>
              <div class="dialog-actions">
                <button class="button button-secondary" type="button" value="cancel" data-close autofocus>
                  Cancel
                </button>
                <button class="button button-danger" type="button" value="delete" data-confirm>
                  Delete image
                </button>
              </div>
            </div>
          </dialog>
        `;
      }

      function App() {
        return `
          <div class="app-shell">
            ${Header()}
            <main id="main-content">
              <section class="hero" aria-label="Image preview and details">
                ${ImagePreview()}
                ${DetailsPanel()}
              </section>
            </main>
          </div>
          ${DeleteDialog()}
        `;
      }

      function bindDialog() {
        const dialog = document.getElementById("delete-dialog");
        const trigger = document.querySelector(".trigger");
        const closeButton = dialog.querySelector("[data-close]");
        const confirmButton = dialog.querySelector("[data-confirm]");

        trigger.addEventListener("click", () => {
          if (!dialog.open) {
            dialog.showModal();
          }
        });

        closeButton.addEventListener("click", () => {
          dialog.close("cancel");
        });

        confirmButton.addEventListener("click", () => {
          dialog.close("delete");
        });

        dialog.addEventListener("click", (event) => {
          if (event.target === dialog) {
            dialog.close("cancel");
          }
        });

        dialog.addEventListener("close", () => {
          if (dialog.returnValue === "delete") {
            isDeleted = true;
            render();
            document.getElementById("delete-status").focus();
          }
        });
      }

      function render() {
        document.getElementById("app").innerHTML = App();
        bindDialog();
      }

      render();
    </script>
  </body>
</html>
